%% code to flashn = 11;%generate a single 12 bit codeword.%find all its shifts. add them to dictionary.%and inversions%go to next word. if its not in dictionary then add itdict = zeros(2^n,1,'uint8');codes = []; cnt = 0;msb = 2^n;for c=1:(2^n-2)    inDict = false;    c_ = double(dec2bin(c+msb)==49);    c_ = c_(2:end);    ind = zeros(n,1);    for j = 1:n        c_ = c_([2:end 1]);        ind(j) = bin2dec(char(48+(dec2bin(c_)'==49))) ;        if dict(ind(j)+1)            inDict = true;            %dict(ind(j)+1)=dict(ind(j)+1)+1;            continue;        end    end    if ~inDict        further3 = true;        if 1 % find distance to everyone already in dictionary (similar to furthest point)                        for j = 1:n                for k=0:size(dict,1)-1                    if (dict(k+1))                        d=disthamming(uint16(ind(j)),uint16(k));                        if d<3                            further3=false;                        end                                               end                end            end        end        if further3                        cnt = cnt+1;            codes(cnt) = c;            for j = 1:n                dict(ind(j)+1) = 1;            end        end        % disp(c);    endenddec2bin(codes)size(codes)ffsfsd%% 1-2, 2-3, 3-4, 4-6, 5-8, 6-14, 7-20, 8-36, 9-60,10-108,11-188,12-352,13-632,14-1182, 15 -2192, 16-4116numCodes = [2 3 4 6 8 14 20 36 60 108 188 352 632 1182 2192 4116];n = 15;%generate a single 12 bit codeword.%find all its shifts. add them to dictionary.%and inversions%go to next word. if its not in dictionary then add itdict = zeros(2^n,1,'uint8');codes = []; cnt = 0;msb = 2^n;for c=0:(2^n-1)    inDict = false;    c_ = double(dec2bin(c,n)=='1');    ind = zeros(n,1);    for j = 1:n                ind(j) = bin2dec(char('0'+(dec2bin(c_)'=='1'))) ;        if dict(ind(j)+1)            inDict = true;            %dict(ind(j)+1)=dict(ind(j)+1)+1;            break;        end        c_ = c_([2:end 1]);    end    if ~inDict        cnt = cnt+1;        codes(cnt) = c;        for j = 1:n            dict(ind(j)+1) = 1;        end        % disp(c);    endenddec2bin(codes)size(codes)%% Create adjacency matrix using noiseball overlap.% In other words if two nodes share a code then they are adjacentD=[];C={};for i=1:length(codes)    c=codes(i);    c_ = double(dec2bin(c,n)=='1');    ind = zeros(n,1);    cc = [];    for j = 1:n        code = char('0'+(dec2bin(c_)'=='1'));        ind(j) = bin2dec(code) ;        cc=[cc ind(j)];        [~,~,~,V] = genNoise(code=='1');        cc=[cc V];        c_ = c_([2:end 1]);    end    C{i}=unique(cc);endfor i=1:length(codes)    for j=i+1:length(codes)        d=length(intersect(C{i},C{j}))~=0;        D(i,j)=d;        D(j,i)=d;    endend%% create a codeword waveform and sample it using a delta comb% however, the major issue when there is no synch is that the sampling% frequency defined by nyquist wont work  for a square waveform because% it has an infinite frequency support.% if instead we used haar wavelets then we would accurately need to know% the width of the wavelet for each beacon: which we dont know ...% i think the only "solution" is to define codewords% Also, the plan to get the code bit values is to take the last n bits, and find the% smallest value and use that as the baseline. This assumes that neither% 0000 or 1111 are codewords. It also assumes that the difference over% small time frames in brightness is minimal.% We need to check that the smallest and the largest have a sufficiently% large ratio otherwise we cannot count on it.%Very fast LED led rise time is less than 1us so we%assume that led signal frequency with a sign wave needs at least 1MHz%representationfs=1e6; %1MHz (at least)df = 200e-6; %percentage frequency drift of code clock using arduinof=120*(1+df); %Frequency of codes is two camera framesnCyl=n+1; % show one full codeword and slight borderst=0:1/fs:nCyl*1/f; %time indexc = dec2bin(msb+codes(randi(numCodes(n)-2)+1));c=c(2:end);ofst = 1/fs + 1/f;x=t*0; x(uint32((ofst+(0:1/f:(n-1)/f))/(1/fs))) = (double(c)-48)+1; % create impulse pointsx=conv(x,ones(1,uint32(floor((1/f)/(1/fs)))),'same');title(['CODE: ' c]);xlabel('Time(s)');ylabel('Detected bit');df2 = -200e-6;fs1=120*(1+df2); % camera sampling frequency%%for ofst1=-0.1:1/fs*200:0.1    t1=ofst1+(0:1/fs1:nCyl*2/f); %time index    x1=interp1(t,x,t1);    cla    plot(t,x);    hold on;    stem(t1,x1);    xx=char(x1(~isnan(x1) & x1~=0)-1+48);        %% xx is the last 20 measured bits at any given moment    disp(xx);        %% Put your conversion code here    %% It needs to produce the same code displayed in the            %%            drawnow    end%% Try to create a dictionary of codes so we can see the distributionn = 11;%generate a single 12 bit codeword.%find all its shifts. add them to dictionary.%and inversions%go to next word. if its not in dictionary then add itdict = zeros(2^n,1,'uint8');codes = []; cnt = 0;msb = 2^n;% create list of codes with cyclic completenessfor c=0:(2^n-1)    inDict = false;    c_ = double(dec2bin(c+msb)==49);    c_ = c_(2:end);    ind = zeros(n,1);    for j = 1:n        c_ = c_([2:end 1]);        % store the code which has been cycled        ind(j) = bin2dec(char(48+(dec2bin(c_)'==49))) ;        %check if this code is already in the dictionary. if yes then        % the mother code is already there and we dont add it again        if dict(ind(j)+1)            inDict = true;            %dict(ind(j)+1)=dict(ind(j)+1)+1;            continue;        end    end    if ~inDict            cnt = cnt+1;            codes(cnt) = c;            for j = 1:n                dict(ind(j)+1) = c+1;            end    endenddec2bin(codes)size(codes)% Go over all codes and find distance (using cyclic equivalence)for i=2:length(codes)-1 % we ignore the all-0 and all-1 codes    ind = zeros(n,1);    c=codes(i);    c_ = double(dec2bin(c+msb)==49);    c_ = c_(2:end);    for j = 1:n        c_ = c_([2:end 1]);        ind(j) = bin2dec(char(48+(dec2bin(c_)'==49))) ;    end    % Get all the cyclically equivalent codewords for c    H{i-1} = (unique(ind));    h=H{i-1};    m=[];        % Go over all the code words for c and find the smallest    % intra-code distance.    for k=2:length(h)        m(k-1) = disthamming(uint16(h(1)),uint16(h(k)));    end    % store    Mintra(i-1) = min(m);end% Now find all the inter-code distancesfor i=1:length(H)    h = H{i};    hi=h(1);    for j=1:length(H)        hj = H{j};        m=[];        for k=1:length(hj)            m(k) = disthamming(uint16(hi),uint16(hj(k)));        end        Minter(i,j) = min(m);    endend% Find maximal clique[mc] = findmaximalclique(Minter>2);%% create bit skips randomization!!!%